export const FitnessProfileService = {
  /**
   * Calculate Basal Metabolic Rate (BMR) using the validated Mifflin-St Jeor formula.
   */
  calculateBMR(weightKg: number, heightCm: number, age: number, gender: Gender = 'male'): number {
    const base = 10 * weightKg + 6.25 * heightCm - 5 * age;
    if (gender === 'male') {
      return Math.round(base + 5);
    } else if (gender === 'female') {
      return Math.round(base - 161);
    }
    // Midpoint for non-binary or unstated
    return Math.round(base - 78);
  },

  /**
   * Calculate Total Daily Energy Expenditure (TDEE).
   */
  calculateTDEE(bmr: number, activityLevel: ActivityLevel): number {
    const multipliers: Record<ActivityLevel, number> = {
      sedentary: 1.2,
      lightly_active: 1.375,
      moderately_active: 1.55,
      very_active: 1.725,
    };
    return Math.round(bmr * (multipliers[activityLevel] || 1.375));
  },

  /**
   * Calculate Daily Calorie & Macronutrient Targets with safe floors.
   */
  calculateNutritionTargets(
    tdee: number,
    goal: FitnessGoal,
    weightKg: number,
    gender: Gender = 'male'
  ): {
    calorieTarget: number;
    proteinG: number;
    carbsG: number;
    fatG: number;
    waterMl: number;
  } {
    let calorieTarget = tdee;
    const minCalories = gender === 'female' ? 1200 : 1500;

    switch (goal) {
      case 'weight_loss':
        calorieTarget = Math.max(minCalories, tdee - 500); // 500 kcal deficit
        break;
      case 'muscle_gain':
        calorieTarget = tdee + 350; // Clean lean surplus
        break;
      case 'endurance':
        calorieTarget = tdee + 150;
        break;
      case 'maintenance':
      case 'general_fitness':
      default:
        calorieTarget = tdee;
        break;
    }

    // Protein: 1.8g - 2.0g per kg for muscle gain & weight loss (muscle sparing)
    const proteinMultiplier = goal === 'muscle_gain' || goal === 'weight_loss' ? 2.0 : 1.6;
    const proteinG = Math.round(weightKg * proteinMultiplier);
    const proteinCalories = proteinG * 4;

    // Fat: 25% of total caloric intake
    const fatCalories = calorieTarget * 0.25;
    const fatG = Math.round(fatCalories / 9);

    // Carbs: Remaining calories
    const remainingCalories = Math.max(0, calorieTarget - proteinCalories - fatCalories);
    const carbsG = Math.round(remainingCalories / 4);

    // Hydration: 35ml per kg bodyweight + 500ml activity allowance
    const waterMl = Math.round(weightKg * 35 + 500);

    return {
      calorieTarget,
      proteinG,
      carbsG,
      fatG,
      waterMl,
    };
  },

  /**
   * Determine recommended daily step goal based on activity and goal.
   */
  calculateStepGoal(activityLevel: ActivityLevel, goal: FitnessGoal): number {
    if (activityLevel === 'very_active') return 12000;
    if (activityLevel === 'moderately_active') return 10000;
    if (goal === 'weight_loss') return 9500;
    if (activityLevel === 'lightly_active') return 8000;
    return 7000;
  },

  /**
   * Unit conversion helpers
   */
  converters: {
    lbsToKg: (lbs: number) => Math.round((lbs * 0.453592) * 10) / 10,
    kgToLbs: (kg: number) => Math.round((kg * 2.20462) * 10) / 10,
    ftInToCm: (ft: number, inches: number) => Math.round((ft * 12 + inches) * 2.54),
    cmToFtIn: (cm: number) => {
      const totalInches = cm / 2.54;
      const ft = Math.floor(totalInches / 12);
      const inches = Math.round(totalInches % 12);
      return { ft, inches };
    },
  },

  /**
   * Fetch user fitness profile from Supabase or user store.
   */
  async getFitnessProfile(userId?: string): Promise<FitnessProfile> {
    const targetId = userId || AuthService.getActiveUserId();
    if (BackendApi.hasAuthToken()) {
      const response = await BackendApi.getFitnessProfile();
      if (response.profile) {
        const remote = toFitnessProfile(response.profile, targetId);
        UserStore.saveFitnessProfile(remote);
        return remote;
      }
    }
    const stored = UserStore.getFitnessProfile(targetId);
    if (stored) return stored;

    // Default baseline for new user
    const defaultProfile: FitnessProfile = {
      id: `fit_${targetId}`,
      userId: targetId,
      heightCm: 175,
      weightKg: 70,
      targetWeightKg: 68,
      fitnessGoal: 'weight_loss',
      fitnessLevel: 'beginner',
      activityLevel: 'sedentary',
      workoutPreference: 'home',
      availableEquipment: ['bodyweight'],
      preferredWorkoutDurationMin: 20,
      weeklyWorkoutFrequencyDays: 3,
      dietaryPreference: 'non_vegetarian',
      allergiesAndRestrictions: ['none'],
      bmr: 1650,
      tdee: 1980,
      dailyCalorieTarget: 1500,
      dailyProteinG: 140,
      dailyCarbsG: 160,
      dailyFatG: 45,
      dailyStepGoal: 8000,
      dailyWaterMl: 2500,
      isPrivate: true,
      updatedAt: new Date().toISOString(),
    };
    UserStore.saveFitnessProfile(defaultProfile);
    return defaultProfile;
  },

  /**
   * Save or update fitness profile.
   */
  async saveFitnessProfile(
    profileData: Omit<FitnessProfile, 'id' | 'bmr' | 'tdee' | 'dailyCalorieTarget' | 'dailyProteinG' | 'dailyCarbsG' | 'dailyFatG' | 'dailyStepGoal' | 'dailyWaterMl' | 'updatedAt'>,
    age: number = 28,
    gender: Gender = 'male'
  ): Promise<FitnessProfile> {
    const targetUserId = profileData.userId || AuthService.getActiveUserId();
    const bmr = this.calculateBMR(profileData.weightKg, profileData.heightCm, age, gender);
    const tdee = this.calculateTDEE(bmr, profileData.activityLevel);
    const nutrition = this.calculateNutritionTargets(tdee, profileData.fitnessGoal, profileData.weightKg, gender);
    const dailyStepGoal = this.calculateStepGoal(profileData.activityLevel, profileData.fitnessGoal);

    let completeProfile: FitnessProfile = {
      ...profileData,
      id: `fit_${targetUserId}`,
      userId: targetUserId,
      bmr,
      tdee,
      dailyCalorieTarget: nutrition.calorieTarget,
      dailyProteinG: nutrition.proteinG,
      dailyCarbsG: nutrition.carbsG,
      dailyFatG: nutrition.fatG,
      dailyWaterMl: nutrition.waterMl,
      dailyStepGoal,
      updatedAt: new Date().toISOString(),
    };

    const response = await BackendApi.saveFitnessProfile({
      heightCm: completeProfile.heightCm,
      weightKg: completeProfile.weightKg,
      targetWeightKg: completeProfile.targetWeightKg,
      fitnessGoal: completeProfile.fitnessGoal,
      fitnessLevel: completeProfile.fitnessLevel,
      activityLevel: completeProfile.activityLevel,
      workoutPreference: completeProfile.workoutPreference,
      availableEquipment: completeProfile.availableEquipment,
      preferredWorkoutDurationMin: completeProfile.preferredWorkoutDurationMin,
      weeklyWorkoutFrequencyDays: completeProfile.weeklyWorkoutFrequencyDays,
      dietaryPreference: completeProfile.dietaryPreference,
      allergiesAndRestrictions: completeProfile.allergiesAndRestrictions,
      dailyStepGoal: completeProfile.dailyStepGoal,
      isPrivate: completeProfile.isPrivate,
    });
    completeProfile = toFitnessProfile(response.profile, targetUserId);
    UserStore.saveFitnessProfile(completeProfile);

    return completeProfile;
  },
};

function toFitnessProfile(row: Record<string, any>, userId: string): FitnessProfile {
  const number = (key: string, fallback = 0) => Number(row[key] ?? fallback);
  return {
    id: row.id,
    userId,
    heightCm: number('height_cm'),
    weightKg: number('weight_kg'),
    targetWeightKg: row.target_weight_kg == null ? undefined : number('target_weight_kg'),
    fitnessGoal: row.fitness_goal,
    fitnessLevel: row.fitness_level,
    activityLevel: row.activity_level,
    workoutPreference: row.workout_preference,
    availableEquipment: row.available_equipment || ['bodyweight'],
    preferredWorkoutDurationMin: number('preferred_workout_duration_min', 30),
    weeklyWorkoutFrequencyDays: number('weekly_workout_frequency_days', 4),
    dietaryPreference: row.dietary_preference,
    allergiesAndRestrictions: row.allergies_and_restrictions || [],
    bmr: number('bmr'),
    tdee: number('tdee'),
    dailyCalorieTarget: number('daily_calorie_target'),
    dailyProteinG: number('daily_protein_g'),
    dailyCarbsG: number('daily_carbs_g'),
    dailyFatG: number('daily_fat_g'),
    dailyStepGoal: number('daily_step_goal', 10000),
    dailyWaterMl: number('daily_water_ml', 2500),
    isPrivate: row.is_private !== false,
    updatedAt: row.updated_at || new Date().toISOString(),
  };
}
